pub(crate) fn read8(address: u64) -> Option<u8> {
    let rva = address.checked_sub(super::end_source32b_core::LIB_BASE)?;
    let page = rva & !0xfff;
    let offset = (rva & 0xfff) as usize;
    let table: &[u8; 4096] = match page {
        0x08000 => &PAGE_08000,
        _ => return None,
    };
    Some(table[offset])
}
